import{_ as o,c as t,o as a,ag as i}from"./chunks/framework.ko2zIC2c.js";const p=JSON.parse('{"title":"Basic Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/lightframe/index.md","filePath":"en/docs/lightframe/index.md"}'),r={name:"en/docs/lightframe/index.md"};function n(l,e,s,c,u,d){return a(),t("div",null,e[0]||(e[0]=[i('<h1 id="basic-introduction" tabindex="-1">Basic Introduction <a class="header-anchor" href="#basic-introduction" aria-label="Permalink to &quot;Basic Introduction&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Official Website: <a href="https://lightframe.vilinko.com/" target="_blank" rel="noreferrer">LightFrame - Define Your Favorite Desktop</a></li><li>Developer: <a href="https://github.com/EnderMo" target="_blank" rel="noreferrer">沫狐奶昔 CimiMoly</a></li></ul></div><h2 id="software-features" tabindex="-1">Software Features <a class="header-anchor" href="#software-features" aria-label="Permalink to &quot;Software Features&quot;">​</a></h2><ul><li>Ready to use. Using a self-developed lightweight framework to achieve extremely low resource usage<sup>1</sup>, ensuring smooth daily use while meeting desktop experience needs.</li><li>Create a desktop you love with in-app clock, calendar, sticky notes and other components<sup>2</sup>. In addition, you can use mixing and component cutting functions to make it more suitable for your wallpaper.</li><li>Focus on your experience. The application provides a focus space function, allowing you to easily organize your tasks. At the same time, you can arrange it with desktop components to create a richer daily experience.</li><li>This application never enforces charges. Of course, if you have the ability, we hope you can support this application to help us develop and maintain it for a long time.</li></ul><sup> 1. Under normal circumstances, the running memory does not exceed 10MB.<br> 2. Please check the prompts in the application for related content. </sup><h2 id="bug-feedback" tabindex="-1">Bug Feedback <a class="header-anchor" href="#bug-feedback" aria-label="Permalink to &quot;Bug Feedback&quot;">​</a></h2><p>You can feedback bugs through the following two channels:</p><ol><li>Visit the <a href="https://forum.vilinko.com/" target="_blank" rel="noreferrer">forum</a>, register an account and post for help</li><li>Add the room manager&#39;s QQ: 2016860442, collect error information and feedback bugs</li></ol><p>Please provide the <strong>.vui</strong> file under the <code>C:\\Users\\username\\AppData\\Roaming\\LightFrame</code> folder, which will help determine the bug For the way of asking questions, please refer to <a href="https://forum.vilinko.com/d/34-ban-yun-ti-wen-de-yi-zhu" target="_blank" rel="noreferrer">【Repost】The Art of Asking Questions - Vilinko Studio</a></p><h2 id="about-program-customization" tabindex="-1">About Program Customization <a class="header-anchor" href="#about-program-customization" aria-label="Permalink to &quot;About Program Customization&quot;">​</a></h2><p>Customization is essentially a kind of support for the work~ Compared to direct sponsorship, you also get the special version you want owo</p><h3 id="customizable-range" tabindex="-1">Customizable Range <a class="header-anchor" href="#customizable-range" aria-label="Permalink to &quot;Customizable Range&quot;">​</a></h3><ul><li>Home background color (solid color/gradient)</li><li>Title bar color (solid color/gradient)</li><li>Buttons (solid color rounded corners/solid color right angles/solid color gradient)</li><li>Add/modify/delete interfaces (such as position/text/banner content/component or window style)</li><li>Specific UI</li><li>vui cards (custom sticky note style)</li><li>Personal practical functions (this takes a lot of time to do!)</li><li>etc.</li></ul><p>In the customized version, you can also set a special logo for yourself to display anywhere in the program Such as: title bar gold gradient &quot; &quot;</p><h3 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h3><p><strong>Starting from 15 RMB</strong> You can bid according to your subjective customization value (it takes some time to modify the source code specifically for customization w) People who have sponsored more than 10 RMB can directly get a private customization opportunity</p><h3 id="construction-period" tabindex="-1">Construction Period <a class="header-anchor" href="#construction-period" aria-label="Permalink to &quot;Construction Period&quot;">​</a></h3><p>Generally, the customized application will be delivered within 14 days on school days QwQ Completed on the same day during long vacations or double weekends</p><p><strong>Add the author&#39;s QQ: 2016860442 and make a request directly</strong> Or make a reservation in the private message of Afdian~ If you want to update the customization to the new version, you can bid again<sub>No need to update at the original price!</sub></p><h2 id="about-updates" tabindex="-1">About Updates <a class="header-anchor" href="#about-updates" aria-label="Permalink to &quot;About Updates&quot;">​</a></h2><p>LightFrame <strong>will not</strong> update automatically, it will only start when the user clicks the <strong>Check for Updates</strong> button</p><p>The update process is as follows:</p><ol><li>Download the updater online<sup>1</sup></li><li>The updater downloads the new version files</li><li>Unzip and overwrite to update</li></ol><sup> 1. Call the local cache directly when there is an updater in the local cache </sup><h2 id="other-information" tabindex="-1">Other Information <a class="header-anchor" href="#other-information" aria-label="Permalink to &quot;Other Information&quot;">​</a></h2><p>For contributors and update logs, please refer to the official website: <a href="https://lightframe.vilinko.com" target="_blank" rel="noreferrer">https://lightframe.vilinko.com</a></p>',26)]))}const m=o(r,[["render",n]]);export{p as __pageData,m as default};
